parameters.jsCode:
const source =
  $('Code - chunk complete document').first().json;

const chunks =
  Array.isArray(source.chunks)
    ? source.chunks
    : [];

if (!chunks.length) {
  throw new Error(
    `TextUUID ${source.TextUUID}: keine Chunks vorhanden`
  );
}

return chunks.map(chunk => ({
  json: {
    TextUUID:
      source.TextUUID,

    ChunkSprache:
      '?',

    ChunkChunkNumber:
      Number(chunk.counter),

    ChunkText:
      chunk.text ?? '',

    ChunkPageFrom:
      chunk.page_from ?? null,

    ChunkPageTo:
      chunk.page_to ?? null
  }
}));

const items = $input.all();

return items.map(item => {
  const part = item.json;

  const hasDoclingJSON =
    typeof part.DoclingJSON === 'string'
      ? part.DoclingJSON.trim() !== ''
      : part.DoclingJSON != null;

  const hasPaddleJSON =
    typeof part.PaddleJSON === 'string'
      ? part.PaddleJSON.trim() !== ''
      : part.PaddleJSON != null;

  const hasDoclingMD =
    typeof part.DoclingMD === 'string'
      ? part.DoclingMD.trim() !== ''
      : part.DoclingMD != null;

  let SourceType = null;

  // Primär anhand dessen, was tatsächlich gespeichert wurde.
  if (hasDoclingJSON) {
    SourceType = 'docling_json';
  } else if (hasPaddleJSON) {
    SourceType = 'paddle_json';
  } else if (hasDoclingMD) {
    SourceType = 'docling_md';
  }

  if (!SourceType) {
    throw new Error(
      `Part ${part.PartNumber} / PartID ${part.PartID}: ` +
      `keine verwertbaren Extraktionsdaten vorhanden`
    );
  }

  return {
    json: {
      ...part,
      SourceType,
      PageOffset: Number(part.PageFrom) - 1
    }
  };
});

const item = $json;

const partNumber = Number(item.PartNumber);
const partId = Number(item.PartID);
const pageOffset = Number(item.PageOffset ?? 0);

function asArray(x) {
  return Array.isArray(x) ? x : [];
}

function refId(refObj) {
  return refObj && typeof refObj.$ref === 'string'
    ? refObj.$ref
    : '';
}

function localPageNo(item) {
  const value = item?.prov?.[0]?.page_no;

  if (
    value === undefined ||
    value === null ||
    value === ''
  ) {
    return null;
  }

  const n = Number(value);

  return Number.isFinite(n)
    ? n
    : null;
}

/*
 * Vorerst Annahme: Docling page_no ist 1-basiert.
 * Falls wir später feststellen, dass page_no 0-basiert ist,
 * ändern wir genau diese Funktion.
 */
function globalPageNo(item) {
  const local = localPageNo(item);

  if (local === null) {
    return null;
  }

  return local + pageOffset;
}

function normalizeCellText(s) {
  return String(s || '')
    .trim()
    .replace(/\s+/g, ' ');
}

let document = {};

try {
  document =
    typeof item.DoclingJSON === 'string'
      ? JSON.parse(item.DoclingJSON)
      : item.DoclingJSON;
} catch (e) {
  throw new Error(
    `Part ${partNumber}: DoclingJSON ist kein gültiges JSON`
  );
}

const bodyChildren = asArray(document?.body?.children);
const texts = asArray(document?.texts);
const groups = asArray(document?.groups);
const tables = asArray(document?.tables);

const entries = [];

let lastLabel = '';
let textblock = '';
let heading = '';
let pageFrom = null;
let pageTo = null;

function findTextByRef(ref) {
  return texts.find(t => t?.self_ref === ref);
}

function pushTextEntry() {
  if (!textblock && !heading) {
    return;
  }

  entries.push({
    type: 'text',
    heading,
    text: textblock,
    page_from: pageFrom,
    page_to: pageTo,

    part_number: partNumber,
    part_id: partId
  });

  textblock = '';
  heading = '';
  pageFrom = null;
  pageTo = null;
}

function handleTextItem(t) {
  const label = t?.label || '';
  const original = t?.orig || '';
  const text = t?.text || '';
  const hyperlink = t?.hyperlink || '';

  const currentPage = globalPageNo(t);

  if (currentPage !== null) {
    pageTo = currentPage;

    if (pageFrom === null) {
      pageFrom = currentPage;
    }
  }

  if (label === 'section_header') {
    if (textblock) {
      pushTextEntry();
    }

    if (heading) {
      heading += '\n' + text;
    } else {
      heading = text;
    }
  }

  else if (label === 'list_item') {
    if (
      textblock &&
      !textblock.endsWith('\n')
    ) {
      textblock += '\n';
    }

    if (original) {
      textblock += original.trim();
    } else if (text) {
      textblock += `- ${text.trim()}`;
    }

    if (hyperlink) {
      textblock += ` (${hyperlink})`;
    }

    textblock += '\n';
  }

  else if (label === 'text') {
    if (
      textblock &&
      !/[ \n]$/.test(textblock)
    ) {
      textblock += ' ';
    }

    if (text) {
      textblock += text.trim();

      if (hyperlink) {
        textblock += ` (${hyperlink})`;
      }
    }
  }

  lastLabel = label;
}

function normalizeTable(tab) {
  const data = tab?.data || {};
  const cells = asArray(data.table_cells);

  let hasColumnHeaders = false;
  let maxRow = 0;
  let maxCol = 0;

  const defs = cells.map(tc => {
    const def = {
      text: normalizeCellText(tc?.text),
      row_header: !!tc?.row_header,
      column_header: !!tc?.column_header,
      row_span: tc?.row_span || 1,
      col_span: tc?.col_span || 1,
      start_row: tc?.start_row_offset_idx || 0,
      start_col: tc?.start_col_offset_idx || 0,
    };

    hasColumnHeaders ||= def.column_header;

    maxRow = Math.max(
      maxRow,
      def.start_row + def.row_span
    );

    maxCol = Math.max(
      maxCol,
      def.start_col + def.col_span
    );

    return def;
  });

  if (!maxRow || !maxCol) {
    return '';
  }

  const grid = Array.from(
    { length: maxRow },
    () =>
      Array.from(
        { length: maxCol },
        () => ({
          text: '',
          row_header: false,
          column_header: false,
        })
      )
  );

  for (const cell of defs) {
    for (
      let r = cell.start_row;
      r < cell.start_row + cell.row_span;
      r++
    ) {
      for (
        let c = cell.start_col;
        c < cell.start_col + cell.col_span;
        c++
      ) {
        grid[r][c].text =
          grid[r][c].text
            ? `${grid[r][c].text} / ${cell.text}`
            : cell.text;

        grid[r][c].row_header ||= cell.row_header;
        grid[r][c].column_header ||= cell.column_header;
      }
    }
  }

  const lines = [];

  if (!hasColumnHeaders) {
    for (let r = 0; r < maxRow; r++) {
      const line = grid[r]
        .map(c => c.text)
        .join(' ')
        .trim();

      if (line) {
        lines.push(line);
      }
    }
  } else {
    for (let r = 1; r < maxRow; r++) {
      const parts = [];

      for (let c = 0; c < maxCol; c++) {
        const header =
          grid[0][c].text ||
          `Column ${c + 1}`;

        const value =
          grid[r][c].text || '';

        parts.push(
          `${header}: ${value};`
        );
      }

      const line =
        parts.join(' ').trim();

      if (line) {
        lines.push(line);
      }
    }
  }

  return lines.join('\n').trim();
}

function handleTableRef(ref) {
  if (textblock || heading) {
    pushTextEntry();
  }

  const tab =
    tables.find(t => t?.self_ref === ref);

  if (!tab) {
    return;
  }

  const currentPage =
    globalPageNo(tab);

  let caption = '';

  for (const cap of asArray(tab.captions)) {
    const t =
      findTextByRef(refId(cap));

    if (t?.text) {
      caption += '\n' + t.text;
    }
  }

  const tableHeading =
    caption
      ? caption
          .replace(/\n/g, ' ')
          .trim()
      : '';

  const tableText =
    normalizeTable(tab);

  if (tableText) {
    entries.push({
      type: tableHeading
        ? 'table'
        : 'text',

      heading: tableHeading,
      text: tableText,

      page_from: currentPage,
      page_to: currentPage,

      part_number: partNumber,
      part_id: partId
    });
  }

  textblock = '';
  heading = '';
  pageFrom = null;
  pageTo = null;
  lastLabel = 'table';
}

for (const bc of bodyChildren) {
  const ref = refId(bc);

  if (!ref) {
    continue;
  }

  if (ref.includes('/texts/')) {
    const t =
      findTextByRef(ref);

    if (t) {
      handleTextItem(t);
    }
  }

  else if (ref.includes('/groups/')) {
    const group =
      groups.find(
        g => g?.self_ref === ref
      );

    for (
      const gc of asArray(group?.children)
    ) {
      const childRef =
        refId(gc);

      const t =
        findTextByRef(childRef);

      if (t) {
        handleTextItem(t);
      }
    }
  }

  else if (ref.includes('/tables/')) {
    handleTableRef(ref);
  }
}

if (textblock || heading) {
  pushTextEntry();
}

return {
  json: {
    PartID: partId,
    QueueID: Number(item.QueueID),
    TextUUID: item.TextUUID,

    PartNumber: partNumber,
    PageFrom: Number(item.PageFrom),
    PageTo: Number(item.PageTo),
    PageOffset: pageOffset,
    SourceType: item.SourceType,

    entries
  }
};

const item = $json;

const partNumber = Number(item.PartNumber);
const partId = Number(item.PartID);
const queueId = Number(item.QueueID);
const pageOffset = Number(item.PageOffset ?? 0);

function asArray(value) {
  return Array.isArray(value) ? value : [];
}

function normalizeText(value) {
  return String(value ?? '')
    .replace(/\r\n?/g, '\n')
    .replace(/\\n/g, '\n')
    .replace(/[ \t]+\n/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function decodeHtml(value) {
  const named = {
    amp: '&',
    quot: '"',
    apos: "'",
    lt: '<',
    gt: '>',
    nbsp: ' ',
  };

  return String(value ?? '')
    .replace(/&#x([0-9a-f]+);/gi, (_, hex) =>
      String.fromCodePoint(parseInt(hex, 16))
    )
    .replace(/&#(\d+);/g, (_, number) =>
      String.fromCodePoint(parseInt(number, 10))
    )
    .replace(/&([a-z]+);/gi, (match, name) =>
      Object.prototype.hasOwnProperty.call(named, name.toLowerCase())
        ? named[name.toLowerCase()]
        : match
    );
}

function htmlToText(value) {
  return normalizeText(
    decodeHtml(
      String(value ?? '')
        .replace(/<br\s*\/?\s*>/gi, '\n')
        .replace(/<\/(p|div|li|h[1-6])\s*>/gi, '\n')
        .replace(/<li\b[^>]*>/gi, '- ')
        .replace(/<[^>]+>/g, ' ')
    ).replace(/[ \t]{2,}/g, ' ')
  );
}

function parsePositiveInt(attributes, name, fallback = 1) {
  const match = String(attributes ?? '').match(
    new RegExp(`${name}\\s*=\\s*["']?(\\d+)`, 'i')
  );

  const value = match ? Number(match[1]) : fallback;

  return Number.isInteger(value) && value > 0
    ? value
    : fallback;
}

function parseHtmlTableRows(html) {
  const rowMatches = [
    ...String(html ?? '').matchAll(
      /<tr\b[^>]*>([\s\S]*?)<\/tr>/gi
    ),
  ];

  const rows = [];
  const spans = [];

  for (const rowMatch of rowMatches) {
    const grid = [];

    for (let column = 0; column < spans.length; column++) {
      const span = spans[column];

      if (!span || span.remaining <= 0) {
        continue;
      }

      grid[column] = span.text;
      span.remaining -= 1;

      if (span.remaining <= 0) {
        spans[column] = null;
      }
    }

    const cells = [
      ...rowMatch[1].matchAll(
        /<(td|th)\b([^>]*)>([\s\S]*?)<\/\1>/gi
      ),
    ];

    let column = 0;

    for (const cell of cells) {
      while (grid[column] !== undefined) {
        column += 1;
      }

      const attributes = cell[2] ?? '';
      const text = htmlToText(cell[3]);

      const rowSpan =
        parsePositiveInt(attributes, 'rowspan');

      const colSpan =
        parsePositiveInt(attributes, 'colspan');

      for (let offset = 0; offset < colSpan; offset++) {
        const targetColumn = column + offset;

        grid[targetColumn] = text;

        if (rowSpan > 1) {
          spans[targetColumn] = {
            text,
            remaining: rowSpan - 1,
          };
        }
      }

      column += colSpan;
    }

    const values = [];
    let previous = null;

    for (const cell of grid) {
      const text = normalizeText(cell);

      if (!text || text === previous) {
        continue;
      }

      values.push(text.replace(/\n+/g, ' / '));
      previous = text;
    }

    if (values.length > 0) {
      rows.push(values.join(' | '));
    }
  }

  return rows;
}

function splitPipeTableRow(line) {
  let value = String(line ?? '').trim();

  if (value.startsWith('|')) {
    value = value.slice(1);
  }

  if (value.endsWith('|')) {
    value = value.slice(0, -1);
  }

  return value
    .split('|')
    .map(cell => normalizeText(cell))
    .filter(Boolean);
}

function parsePipeTableRows(markdown) {
  return normalizeText(markdown)
    .split('\n')
    .filter(line => {
      const value = line.trim();
      return value.startsWith('|') && value.endsWith('|');
    })
    .filter(line => {
      const cells = splitPipeTableRow(line);

      return !(
        cells.length > 0 &&
        cells.every(cell => /^:?-{3,}:?$/.test(cell))
      );
    })
    .map(line =>
      splitPipeTableRow(line).join(' | ')
    )
    .filter(Boolean);
}

function tableRows(value) {
  const content = String(value ?? '');

  if (/<table\b/i.test(content)) {
    return parseHtmlTableRows(content);
  }

  return parsePipeTableRows(content);
}

function isTableLabel(label) {
  return String(label ?? '')
    .toLowerCase()
    .includes('table');
}

function isIgnoredLabel(label) {
  return new Set([
    'header',
    'footer',
    'page_header',
    'page_footer',
    'header_image',
    'footer_image',
    'footnote',
    'number',
    'aside_text',
    'image',
    'picture',
  ]).has(
    String(label ?? '').toLowerCase()
  );
}

function isTitleLabel(label) {
  const value =
    String(label ?? '').toLowerCase();

  return [
    'title',
    'doc_title',
    'document_title',
    'paragraph_title',
    'section_header',
    'heading',
  ].includes(value);
}

function isPageMarker(text) {
  const value = normalizeText(text);

  return (
    /^seite\s*\d+\s*(?:von|\/)?\s*\d*$/i.test(value) ||
    /^page\s*\d+\s*(?:of|\/)?\s*\d*$/i.test(value) ||
    /^\d+\s*(?:von|of|\/)\s*\d+$/i.test(value)
  );
}

function isPlausibleHeading(text) {
  const value =
    normalizeText(text).replace(/\s+/g, ' ');

  if (!value || value.length > 120) {
    return false;
  }

  if (value.split(/\s+/).length > 14) {
    return false;
  }

  if (/[.:;!?]$/.test(value)) {
    return false;
  }

  if (isPageMarker(value)) {
    return false;
  }

  if (
    /^[\s\d.,+-]+(?:EUR|USD|CHF|GBP)?$/i.test(value)
  ) {
    return false;
  }

  return true;
}

/*
 * Liefert bewusst eine 1-basierte lokale Seitennummer.
 */
function localPageNumber(page, index) {
  const explicit =
    page?.page_no ??
    page?.pageNumber ??
    page?.prunedResult?.page_no ??
    page?.prunedResult?.pageNumber;

  if (
    Number.isFinite(Number(explicit)) &&
    Number(explicit) > 0
  ) {
    return Number(explicit);
  }

  const pageIndex =
    page?.page_index ??
    page?.prunedResult?.page_index;

  if (Number.isFinite(Number(pageIndex))) {
    return Number(pageIndex) + 1;
  }

  return index + 1;
}

function globalPageNumber(page, index) {
  return (
    localPageNumber(page, index) +
    pageOffset
  );
}

function orderedBlocks(page) {
  return asArray(
    page?.prunedResult?.parsing_res_list ??
    page?.prunedResult?.parsingResList ??
    page?.parsing_res_list ??
    page?.parsingResList
  )
    .map((block, index) => ({
      block,
      index,
    }))
    .sort((left, right) => {
      const leftOrder =
        Number.isFinite(
          Number(left.block?.block_order)
        )
          ? Number(left.block.block_order)
          : left.index;

      const rightOrder =
        Number.isFinite(
          Number(right.block?.block_order)
        )
          ? Number(right.block.block_order)
          : right.index;

      return leftOrder - rightOrder;
    })
    .map(entry => entry.block);
}

/*
 * PaddleJSON einlesen
 */
const rawPaddleJSON = item.PaddleJSON;

if (
  rawPaddleJSON === undefined ||
  rawPaddleJSON === null ||
  String(rawPaddleJSON).trim() === ''
) {
  throw new Error(
    `Part ${partNumber}: PaddleJSON ist leer`
  );
}

let paddleResponse;

try {
  paddleResponse =
    typeof rawPaddleJSON === 'string'
      ? JSON.parse(rawPaddleJSON)
      : rawPaddleJSON;
} catch (error) {
  throw new Error(
    `Part ${partNumber}: PaddleJSON ist ungültiges JSON: ${error.message}`
  );
}

const response =
  paddleResponse?.body?.result
    ? paddleResponse.body
    : paddleResponse;

if (
  response?.errorCode !== undefined &&
  Number(response.errorCode) !== 0
) {
  throw new Error(
    `Part ${partNumber}: PaddleOCR-VL Fehler ` +
    `${response.errorCode}: ` +
    `${response.errorMsg || 'Unknown error'}`
  );
}

const layoutParsingResults =
  asArray(
    response?.result?.layoutParsingResults ??
    response?.layoutParsingResults
  );

if (layoutParsingResults.length === 0) {
  throw new Error(
    `Part ${partNumber}: PaddleJSON enthält keine layoutParsingResults`
  );
}

const pages =
  layoutParsingResults.map(
    (page, index) => ({
      source: page,

      /*
       * Ab hier ausschließlich globale Seiten.
       */
      pageNumber:
        globalPageNumber(page, index),

      blocks:
        orderedBlocks(page),

      markdown:
        normalizeText(
          page?.markdown?.text ??
          page?.markdown ??
          page?.md_content ??
          ''
        ),
    })
  );

/*
 * Wiederkehrende Kopf-/Fußtexte erkennen.
 * Da pages.pageNumber bereits global ist,
 * arbeitet auch diese Logik direkt mit Originalseiten.
 */
const textPages = new Map();

for (const page of pages) {
  const seenOnPage = new Set();

  for (const block of page.blocks) {
    const label =
      block?.block_label ??
      block?.label ??
      '';

    if (isTableLabel(label)) {
      continue;
    }

    const text =
      htmlToText(
        block?.block_content ??
        block?.content ??
        block?.text ??
        ''
      ).replace(/\s+/g, ' ');

    if (
      !text ||
      text.length > 300 ||
      seenOnPage.has(text)
    ) {
      continue;
    }

    seenOnPage.add(text);

    if (!textPages.has(text)) {
      textPages.set(text, new Set());
    }

    textPages
      .get(text)
      .add(page.pageNumber);
  }
}

function isRepeatedNoise(text) {
  const value =
    normalizeText(text)
      .replace(/\s+/g, ' ');

  const occurrences =
    textPages.get(value);

  return Boolean(
    occurrences &&
    occurrences.size >= 3 &&
    value.length <= 300
  );
}

const entries = [];
let currentEntryNumber = 0;

function addEntry(
  type,
  heading,
  text,
  pageFrom,
  pageTo = pageFrom
) {
  const normalizedHeading =
    normalizeText(heading);

  const normalizedBody =
    normalizeText(text);

  if (
    !normalizedHeading &&
    !normalizedBody
  ) {
    return;
  }

  entries.push({
    source_counter:
      currentEntryNumber++,

    type:
      type || 'text',

    heading:
      normalizedHeading,

    text:
      normalizedBody,

    /*
     * Bereits globale Original-PDF-Seiten.
     */
    page_from:
      pageFrom,

    page_to:
      pageTo,

    part_number:
      partNumber,

    part_id:
      partId,
  });
}

function isLikelyHeaderRow(line) {
  return (
    /(pos\.?|artikelnr\.?|bezeichnung|menge|einzelpreis|gesamtpreis)/i
      .test(String(line ?? ''))
  );
}

function addTableEntries(
  rows,
  heading,
  page
) {
  const normalizedRows =
    rows
      .map(row =>
        normalizeText(row)
          .replace(/\n+/g, ' / ')
      )
      .filter(Boolean);

  if (normalizedRows.length === 0) {
    return;
  }

  const repeatedHeader =
    normalizedRows
      .slice(0, 3)
      .find(isLikelyHeaderRow) ?? '';

  /*
   * Hier noch NICHT auf 3000 Zeichen chunken.
   * Wir erhalten nur semantische Tabellen-Entries.
   */
  for (const row of normalizedRows) {
    addEntry(
      'table',
      heading,
      row,
      page,
      page
    );
  }
}

function parseMarkdownFallback(
  markdown,
  page,
  initialHeading = ''
) {
  const parts =
    String(markdown ?? '')
      .split(
        /(<table\b[\s\S]*?<\/table>)/gi
      )
      .filter(part =>
        normalizeText(part)
      );

  let heading =
    initialHeading;

  for (const part of parts) {
    if (/<table\b/i.test(part)) {
      addTableEntries(
        parseHtmlTableRows(part),
        heading,
        page
      );

      continue;
    }

    const bodyLines = [];

    function flushBody() {
      const text =
        normalizeText(
          bodyLines.join('\n')
        );

      if (text) {
        addEntry(
          'text',
          heading,
          text,
          page,
          page
        );
      }

      bodyLines.length = 0;
    }

    for (
      const line of
      normalizeText(part).split('\n')
    ) {
      const match =
        line
          .trim()
          .match(
            /^(#{1,6})\s+(.+?)\s*#*$/
          );

      if (
        match &&
        isPlausibleHeading(match[2])
      ) {
        flushBody();

        heading =
          normalizeText(match[2]);
      } else if (!isPageMarker(line)) {
        bodyLines.push(
          htmlToText(line)
        );
      }
    }

    flushBody();
  }
}

/*
 * Pages in Dokumentreihenfolge verarbeiten.
 */
for (const page of pages) {
  let currentHeading = '';
  let textBuffer = [];

  function flushTextBuffer() {
    const text =
      normalizeText(
        textBuffer.join('\n\n')
      );

    if (text) {
      addEntry(
        'text',
        currentHeading,
        text,
        page.pageNumber,
        page.pageNumber
      );
    }

    textBuffer = [];
  }

  if (page.blocks.length === 0) {
    parseMarkdownFallback(
      page.markdown,
      page.pageNumber
    );

    continue;
  }

  for (const block of page.blocks) {
    const label =
      String(
        block?.block_label ??
        block?.label ??
        'text'
      ).toLowerCase();

    const rawContent =
      block?.block_content ??
      block?.content ??
      block?.text ??
      '';

    if (isIgnoredLabel(label)) {
      continue;
    }

    if (
      isTableLabel(label) ||
      /<table\b/i.test(
        String(rawContent)
      )
    ) {
      flushTextBuffer();

      addTableEntries(
        tableRows(rawContent),
        currentHeading,
        page.pageNumber
      );

      continue;
    }

    const text =
      htmlToText(rawContent);

    if (
      !text ||
      isPageMarker(text) ||
      isRepeatedNoise(text)
    ) {
      continue;
    }

    if (
      isTitleLabel(label) &&
      isPlausibleHeading(text)
    ) {
      flushTextBuffer();

      currentHeading =
        text.replace(/\s+/g, ' ');

      continue;
    }

    textBuffer.push(text);
  }

  flushTextBuffer();
}

if (entries.length === 0) {
  throw new Error(
    `Part ${partNumber}: PaddleJSON enthält keinen verwertbaren Inhalt`
  );
}

return {
  json: {
    PartID:
      partId,

    QueueID:
      queueId,

    TextUUID:
      item.TextUUID,

    PartNumber:
      partNumber,

    PageFrom:
      Number(item.PageFrom),

    PageTo:
      Number(item.PageTo),

    PageOffset:
      pageOffset,

    SourceType:
      item.SourceType,

    entries
  }
};

const item = $json;

const partNumber = Number(item.PartNumber);
const partId = Number(item.PartID);
const queueId = Number(item.QueueID);
const pageOffset = Number(item.PageOffset ?? 0);

function normalizeText(value) {
  return String(value ?? '')
    .replace(/\\r\\n|\\n|\\r/g, '\n')
    .replace(/\r\n?/g, '\n')
    .replace(/[ \t]+\n/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function markdownString(value) {
  if (value === undefined || value === null) {
    return '';
  }

  if (typeof value === 'string') {
    const trimmed = value.trim();

    if (
      (trimmed.startsWith('"') && trimmed.endsWith('"')) ||
      (trimmed.startsWith("'") && trimmed.endsWith("'"))
    ) {
      try {
        const parsed = JSON.parse(trimmed);

        if (typeof parsed === 'string') {
          return parsed;
        }
      } catch (_) {
        // normaler Markdown-String
      }
    }

    return value;
  }

  if (typeof value === 'object') {
    return markdownString(
      value?.document?.md_content ??
      value?.md_content ??
      value?.DoclingMD ??
      value?.markdown ??
      value?.md ??
      ''
    );
  }

  return String(value);
}

function normalizeInline(value) {
  return String(value ?? '')
    .replace(/<br\s*\/?\s*>/gi, ' / ')
    .replace(/<!--.*?-->/g, ' ')
    .replace(/\\\|/g, '|')
    .replace(/\s+/g, ' ')
    .trim();
}

function stripHeadingMarkup(line) {
  return normalizeInline(
    String(line ?? '')
      .replace(/^\s{0,3}#{1,6}\s+/, '')
  );
}

function headingLevel(line) {
  const match =
    String(line ?? '')
      .match(/^\s{0,3}(#{1,6})\s+/);

  return match
    ? match[1].length
    : 0;
}

function isPageMarker(line) {
  return stripHeadingMarkup(line).match(
    /^seite\s+(\d+)\s+(?:von|\/)\s+(\d+)\s*$/i
  );
}

function splitMarkdownRow(line) {
  const cells = [];
  let cell = '';
  let escaped = false;

  for (const character of String(line ?? '').trim()) {
    if (escaped) {
      cell += character;
      escaped = false;
      continue;
    }

    if (character === '\\') {
      escaped = true;
      continue;
    }

    if (character === '|') {
      cells.push(cell);
      cell = '';
    } else {
      cell += character;
    }
  }

  cells.push(cell);

  if (cells[0]?.trim() === '') {
    cells.shift();
  }

  if (
    cells[cells.length - 1]?.trim() === ''
  ) {
    cells.pop();
  }

  return cells
    .map(normalizeInline);
}

function isTableSeparator(cells) {
  return (
    cells.length > 0 &&
    cells.every(
      cell => /^:?-{3,}:?$/.test(cell)
    )
  );
}

function normalizeTableRow(line) {
  const cells =
    splitMarkdownRow(line);

  if (isTableSeparator(cells)) {
    return '';
  }

  const meaningful = [];

  for (const cell of cells) {
    if (!cell) {
      continue;
    }

    if (
      meaningful[meaningful.length - 1] === cell
    ) {
      continue;
    }

    meaningful.push(cell);
  }

  return meaningful.join(' | ');
}

function isTableLine(line) {
  return /^\s*\|.*\|\s*$/.test(
    String(line ?? '')
  );
}

function canonicalNoise(value) {
  return stripHeadingMarkup(value)
    .toLowerCase()
    .replace(/\s+/g, ' ')
    .trim();
}

function isKnownBoilerplate(value) {
  const text =
    stripHeadingMarkup(value);

  return (
    !text ||
    /^<!--.*-->$/.test(text) ||
    /^biomers\.net GmbH\s*\|/i.test(text) ||
    /Handelsregister.*Ust\.-Id\.\/VAT ID/i.test(text) ||
    /^Geschäftsführer:.*Sparkasse/i.test(text) ||
    /^Sitz des Unternehmens:.*Handelsregister/i.test(text)
  );
}

function isPlausibleHeading(value) {
  const text =
    normalizeInline(value);

  if (!text || text.length > 120) {
    return false;
  }

  if (text.split(/\s+/).length > 14) {
    return false;
  }

  if (/[.:;!?]$/.test(text)) {
    return false;
  }

  if (
    /^[\s\d.,+-]+(?:EUR|USD|CHF|GBP)?$/i
      .test(text)
  ) {
    return false;
  }

  return true;
}

/*
 * Docling-Markdown enthält in deinem bisherigen
 * Parser Marker wie:
 *
 * Seite 1 von 50
 *
 * Diese Nummer ist lokal zum Part.
 */
function splitPages(markdown) {
  const pages = [];
  let lines = [];

  let localPage = 1;

  function flush(pageNumber) {
    const content =
      lines.join('\n').trim();

    if (
      content ||
      pages.length === 0
    ) {
      pages.push({
        localPageNumber: pageNumber,
        globalPageNumber:
          pageNumber + pageOffset,
        content
      });
    }

    lines = [];
  }

  for (
    const line of
    normalizeText(markdown).split('\n')
  ) {
    const marker =
      isPageMarker(line);

    if (marker) {
      const markerPage =
        Number(marker[1]);

      flush(markerPage);

      localPage =
        markerPage + 1;

      continue;
    }

    if (
      /^\s*<!--\s*image\s*-->\s*$/i
        .test(line)
    ) {
      continue;
    }

    lines.push(line);
  }

  if (
    lines.some(line => line.trim())
  ) {
    flush(localPage);
  }

  return pages;
}

const rawMarkdown =
  markdownString(item.DoclingMD);

if (!normalizeText(rawMarkdown)) {
  throw new Error(
    `Part ${partNumber}: DoclingMD ist leer`
  );
}

const pages =
  splitPages(rawMarkdown);

/*
 * Wiederkehrende Header/Footer innerhalb
 * dieses Parts erkennen.
 */
const occurrences =
  new Map();

for (const page of pages) {
  const seen =
    new Set();

  for (
    const line of
    page.content.split('\n')
  ) {
    if (
      isTableLine(line) ||
      isKnownBoilerplate(line)
    ) {
      continue;
    }

    const key =
      canonicalNoise(line);

    if (
      !key ||
      key.length > 400 ||
      seen.has(key)
    ) {
      continue;
    }

    seen.add(key);

    if (!occurrences.has(key)) {
      occurrences.set(
        key,
        new Set()
      );
    }

    occurrences
      .get(key)
      .add(page.globalPageNumber);
  }
}

const repeatedNoise =
  new Set(
    [...occurrences.entries()]
      .filter(
        ([, pageNumbers]) =>
          pageNumbers.size >= 3
      )
      .map(([text]) => text)
  );

const entries = [];
let sourceCounter = 0;

function addEntry(
  type,
  heading,
  text,
  pageFrom,
  pageTo = pageFrom
) {
  const normalizedHeading =
    normalizeInline(heading);

  const normalizedBody =
    normalizeText(text);

  if (
    !normalizedHeading &&
    !normalizedBody
  ) {
    return;
  }

  entries.push({
    source_counter:
      sourceCounter++,

    type:
      type || 'text',

    heading:
      normalizedHeading,

    text:
      normalizedBody,

    page_from:
      pageFrom,

    page_to:
      pageTo,

    part_number:
      partNumber,

    part_id:
      partId
  });
}

function addTableRows(
  rows,
  heading,
  page
) {
  for (const row of rows) {
    const normalized =
      normalizeTableRow(row);

    if (!normalized) {
      continue;
    }

    addEntry(
      'table',
      heading,
      normalized,
      page,
      page
    );
  }
}

for (const page of pages) {
  const lines =
    page.content.split('\n');

  const globalPage =
    page.globalPageNumber;

  let currentHeading = '';
  let paragraph = [];

  function flushParagraph() {
    const text =
      normalizeText(
        paragraph.join('\n')
      );

    if (text) {
      addEntry(
        'text',
        currentHeading,
        text,
        globalPage,
        globalPage
      );
    }

    paragraph = [];
  }

  for (
    let index = 0;
    index < lines.length;
  ) {
    const line =
      lines[index];

    if (isTableLine(line)) {
      flushParagraph();

      const tableLines = [];

      while (
        index < lines.length &&
        isTableLine(lines[index])
      ) {
        tableLines.push(
          lines[index]
        );

        index++;
      }

      addTableRows(
        tableLines,
        currentHeading,
        globalPage
      );

      continue;
    }

    const normalizedLine =
      normalizeInline(line);

    const noiseKey =
      canonicalNoise(line);

    if (
      isKnownBoilerplate(line) ||
      repeatedNoise.has(noiseKey)
    ) {
      index++;
      continue;
    }

    const level =
      headingLevel(line);

    if (level > 0) {
      const heading =
        stripHeadingMarkup(line);

      if (
        isPlausibleHeading(heading)
      ) {
        flushParagraph();

        currentHeading =
          heading;
      } else if (heading) {
        paragraph.push(heading);
      }

      index++;
      continue;
    }

    if (!normalizedLine) {
      if (
        paragraph.length &&
        paragraph[
          paragraph.length - 1
        ] !== ''
      ) {
        paragraph.push('');
      }
    } else {
      paragraph.push(
        normalizedLine
      );
    }

    index++;
  }

  flushParagraph();
}

/*
 * Falls die Markdown-Struktur ungewöhnlich ist,
 * Part nicht einfach verlieren.
 */
if (entries.length === 0) {
  addEntry(
    'text',
    '',
    normalizeText(rawMarkdown),
    Number(item.PageFrom),
    Number(item.PageTo)
  );
}

return {
  json: {
    PartID:
      partId,

    QueueID:
      queueId,

    TextUUID:
      item.TextUUID,

    PartNumber:
      partNumber,

    PageFrom:
      Number(item.PageFrom),

    PageTo:
      Number(item.PageTo),

    PageOffset:
      pageOffset,

    SourceType:
      item.SourceType,

    entries
  }
};

const items = $input.all();

if (!items.length) {
  throw new Error('Keine geparsten Parts erhalten');
}

const parts = items
  .map(item => item.json)
  .sort((a, b) =>
    Number(a.PartNumber) - Number(b.PartNumber)
  );

/*
 * Konsistenz prüfen
 */
const queueIds = new Set(
  parts.map(p => Number(p.QueueID))
);

const textUUIDs = new Set(
  parts.map(p => String(p.TextUUID ?? ''))
);

if (queueIds.size !== 1) {
  throw new Error(
    `Mehrere QueueIDs im Chunk-Dokumentstrom: ${
      [...queueIds].join(', ')
    }`
  );
}

if (textUUIDs.size !== 1) {
  throw new Error(
    `Mehrere TextUUIDs im Chunk-Dokumentstrom: ${
      [...textUUIDs].join(', ')
    }`
  );
}

/*
 * Part-Reihenfolge auf Lücken prüfen.
 */
for (let index = 0; index < parts.length; index++) {
  const expectedPartNumber = index + 1;
  const actualPartNumber =
    Number(parts[index].PartNumber);

  if (actualPartNumber !== expectedPartNumber) {
    throw new Error(
      `Part-Reihenfolge unvollständig: erwartet Part ` +
      `${expectedPartNumber}, erhalten ${actualPartNumber}`
    );
  }
}

/*
 * Entries in Original-Dokumentreihenfolge zusammenführen.
 */
const entries = [];

for (const part of parts) {
  const partEntries =
    Array.isArray(part.entries)
      ? part.entries
      : [];

  if (!partEntries.length) {
    throw new Error(
      `Part ${part.PartNumber} enthält keine Entries`
    );
  }

  for (
    let entryIndex = 0;
    entryIndex < partEntries.length;
    entryIndex++
  ) {
    const entry = partEntries[entryIndex];

    entries.push({
      ...entry,

      part_number:
        Number(part.PartNumber),

      part_id:
        Number(part.PartID),

      source_entry_number:
        entryIndex
    });
  }
}

/*
 * Sicherheitsprüfung der Seitennummern.
 */
for (const entry of entries) {
  const from =
    entry.page_from == null
      ? null
      : Number(entry.page_from);

  const to =
    entry.page_to == null
      ? null
      : Number(entry.page_to);

  if (
    from !== null &&
    (!Number.isInteger(from) || from < 1)
  ) {
    throw new Error(
      `Ungültige page_from=${entry.page_from} ` +
      `in Part ${entry.part_number}`
    );
  }

  if (
    to !== null &&
    (!Number.isInteger(to) || to < 1)
  ) {
    throw new Error(
      `Ungültige page_to=${entry.page_to} ` +
      `in Part ${entry.part_number}`
    );
  }

  if (
    from !== null &&
    to !== null &&
    to < from
  ) {
    throw new Error(
      `Ungültiger Seitenbereich ${from}-${to} ` +
      `in Part ${entry.part_number}`
    );
  }
}

return [{
  json: {
    QueueID:
      Number(parts[0].QueueID),

    TextUUID:
      parts[0].TextUUID,

    TotalParts:
      parts.length,

    TotalEntries:
      entries.length,

    Parts: parts.map(part => ({
      PartID: Number(part.PartID),
      PartNumber: Number(part.PartNumber),
      PageFrom: Number(part.PageFrom),
      PageTo: Number(part.PageTo),
      SourceType: part.SourceType,
      EntryCount:
        Array.isArray(part.entries)
          ? part.entries.length
          : 0
    })),

    entries
  }
}];

const input = $input.first().json;

const MAX_CHARS = 3000;
const MIN_CHARS = 800;

const entries =
  Array.isArray(input.entries)
    ? input.entries
    : [];

if (!entries.length) {
  throw new Error(
    `TextUUID ${input.TextUUID}: keine Entries zum Chunking vorhanden`
  );
}

function normalizeText(value) {
  return String(value ?? '')
    .replace(/\r\n?/g, '\n')
    .replace(/[ \t]+\n/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function normalizeHeading(value) {
  return normalizeText(value)
    .replace(/\n+/g, '\n')
    .trim();
}

function renderEntry(entry) {
  const heading =
    normalizeHeading(entry.heading);

  const body =
    normalizeText(entry.text);

  if (heading && body) {
    return `${heading}\n${body}`.trim();
  }

  return heading || body;
}

function validPage(value) {
  const number = Number(value);

  return Number.isInteger(number) && number > 0
    ? number
    : null;
}

function firstPage(...values) {
  const pages =
    values
      .map(validPage)
      .filter(value => value !== null);

  return pages.length
    ? Math.min(...pages)
    : null;
}

function lastPage(...values) {
  const pages =
    values
      .map(validPage)
      .filter(value => value !== null);

  return pages.length
    ? Math.max(...pages)
    : null;
}

/*
 * Text robust auf MAX_CHARS teilen.
 */
function splitTextSafe(
  value,
  maxChars = MAX_CHARS,
  minChars = MIN_CHARS
) {
  const output = [];

  let remaining =
    normalizeText(value);

  while (remaining) {
    if (remaining.length <= maxChars) {
      output.push(remaining);
      break;
    }

    const window =
      remaining.slice(0, maxChars);

    let cut = -1;

    for (const separator of [
      '\n\n',
      '. ',
      '! ',
      '? ',
      '; ',
      ': ',
      '\n'
    ]) {
      const position =
        window.lastIndexOf(separator);

      if (position >= minChars) {
        cut = Math.max(
          cut,
          position + separator.length
        );
      }
    }

    if (cut < minChars) {
      const whitespace =
        window.lastIndexOf(' ');

      cut =
        whitespace >= minChars
          ? whitespace
          : maxChars;
    }

    const part =
      normalizeText(
        remaining.slice(0, cut)
      );

    if (part) {
      output.push(part);
    }

    remaining =
      normalizeText(
        remaining.slice(cut)
      );
  }

  /*
   * Sehr kleinen letzten Rest möglichst
   * wieder mit dem Vorgänger verbinden.
   */
  if (
    output.length > 1 &&
    output[output.length - 1].length < minChars
  ) {
    const previous =
      output[output.length - 2];

    const last =
      output[output.length - 1];

    const combined =
      `${previous}\n\n${last}`;

    if (combined.length <= maxChars) {
      output.splice(
        output.length - 2,
        2,
        combined
      );
    }
  }

  return output.filter(Boolean);
}

/*
 * Zunächst aus Entries atomare Einheiten machen.
 *
 * Ein Entry kann selbst >3000 Zeichen sein.
 */
const prepared = [];

for (const entry of entries) {
  const text =
    renderEntry(entry);

  if (!text) {
    continue;
  }

  const pageFrom =
    validPage(entry.page_from);

  const pageTo =
    validPage(entry.page_to);

  const parts =
    splitTextSafe(text);

  for (
    let index = 0;
    index < parts.length;
    index++
  ) {
    prepared.push({
      type:
        entry.type || 'text',

      heading:
        index === 0
          ? normalizeHeading(entry.heading)
          : '',

      text:
        parts[index],

      page_from:
        pageFrom,

      page_to:
        pageTo,

      /*
       * Nur Debug-Provenienz.
       * Wird nicht zwingend in if_chunks geschrieben.
       */
      part_from:
        Number(entry.part_number),

      part_to:
        Number(entry.part_number)
    });
  }
}

if (!prepared.length) {
  throw new Error(
    `TextUUID ${input.TextUUID}: alle Entries waren leer`
  );
}

/*
 * Zwei aufeinanderfolgende Chunks vereinigen.
 *
 * Hier dürfen bewusst auch Part-Grenzen
 * überschritten werden.
 */
function mergePair(left, right) {
  const leftText =
    normalizeText(left.text);

  const rightText =
    normalizeText(right.text);

  const headings =
    [
      normalizeHeading(left.heading),
      normalizeHeading(right.heading)
    ]
      .filter(Boolean);

  return {
    type:
      left.type === right.type
        ? left.type
        : 'mixed',

    heading:
      [...new Set(headings)]
        .join('\n'),

    text:
      [leftText, rightText]
        .filter(Boolean)
        .join('\n\n'),

    page_from:
      firstPage(
        left.page_from,
        left.page_to,
        right.page_from,
        right.page_to
      ),

    page_to:
      lastPage(
        left.page_from,
        left.page_to,
        right.page_from,
        right.page_to
      ),

    part_from:
      Math.min(
        Number(left.part_from),
        Number(right.part_from)
      ),

    part_to:
      Math.max(
        Number(left.part_to),
        Number(right.part_to)
      )
  };
}

/*
 * Dokumentstrom der Reihe nach verdichten.
 *
 * Damit verschwindet die technische
 * 50-Seiten-Partgrenze vollständig.
 */
const compacted = [];

for (const current of prepared) {
  const previous =
    compacted[compacted.length - 1];

  if (!previous) {
    compacted.push({
      ...current
    });

    continue;
  }

  const combinedLength =
    normalizeText(previous.text).length +
    normalizeText(current.text).length +
    2;

  if (combinedLength <= MAX_CHARS) {
    compacted[
      compacted.length - 1
    ] = mergePair(
      previous,
      current
    );
  } else {
    compacted.push({
      ...current
    });
  }
}

/*
 * Kurze Chunks (<800) möglichst mit dem
 * Vorgänger vereinigen.
 */
for (
  let index = 1;
  index < compacted.length;
  index++
) {
  const current =
    compacted[index];

  const currentLength =
    normalizeText(current.text).length;

  if (currentLength >= MIN_CHARS) {
    continue;
  }

  const previous =
    compacted[index - 1];

  const previousLength =
    normalizeText(previous.text).length;

  if (
    previousLength +
      currentLength +
      2
    <= MAX_CHARS
  ) {
    compacted.splice(
      index - 1,
      2,
      mergePair(
        previous,
        current
      )
    );

    index--;
  }
}

/*
 * Endgültige Chunknummerierung.
 *
 * ENTSCHEIDEND:
 * genau einmal über das gesamte Dokument.
 */
const chunks =
  compacted.map(
    (chunk, index) => ({
      counter:
        index + 1,

      type:
        chunk.type,

      heading:
        chunk.heading,

      text:
        normalizeText(chunk.text),

      page_from:
        chunk.page_from,

      page_to:
        chunk.page_to,

      part_from:
        chunk.part_from,

      part_to:
        chunk.part_to
    })
  );

/*
 * Optionaler synthetischer Inhalts-/Outline-Chunk.
 * Entspricht dem bisherigen counter=0.
 */
const outline = [];

const seenOutline =
  new Set();

for (const entry of entries) {
  const heading =
    normalizeHeading(entry.heading);

  const page =
    validPage(entry.page_from);

  if (!heading || page === null) {
    continue;
  }

  const key =
    `${heading}\u0000${page}`;

  if (seenOutline.has(key)) {
    continue;
  }

  seenOutline.add(key);

  outline.push(
    `${heading} page ${page}`
  );
}

if (outline.length) {
  chunks.push({
    counter: 0,

    type: 'content',

    heading:
      'Full Content',

    text:
      `Full Content\n${outline.join('\n')}`,

    /*
     * Keine reale Originalseite.
     */
    page_from: null,
    page_to: null,

    part_from: null,
    part_to: null
  });
}

/*
 * Abschließende Invarianten.
 */
const normalChunks =
  chunks.filter(
    chunk => chunk.counter > 0
  );

for (
  let index = 0;
  index < normalChunks.length;
  index++
) {
  const expected =
    index + 1;

  if (
    normalChunks[index].counter !==
    expected
  ) {
    throw new Error(
      `Chunknummerierung inkonsistent: ` +
      `erwartet ${expected}, erhalten ` +
      `${normalChunks[index].counter}`
    );
  }

  if (
    normalChunks[index].text.length >
    MAX_CHARS
  ) {
    throw new Error(
      `Chunk ${expected} überschreitet ` +
      `${MAX_CHARS} Zeichen`
    );
  }

  const from =
    validPage(
      normalChunks[index].page_from
    );

  const to =
    validPage(
      normalChunks[index].page_to
    );

  if (
    from !== null &&
    to !== null &&
    to < from
  ) {
    throw new Error(
      `Chunk ${expected}: ungültiger ` +
      `Seitenbereich ${from}-${to}`
    );
  }
}

return [{
  json: {
    QueueID:
      Number(input.QueueID),

    TextUUID:
      input.TextUUID,

    TotalParts:
      Number(input.TotalParts),

    TotalEntries:
      Number(input.TotalEntries),

    TotalChunks:
      normalChunks.length,

    HasContentChunk:
      outline.length > 0,

    chunks
  }
}];

