const item = $json;

const partNumber = Number(item.PartNumber);
const partId = Number(item.PartID);
const pageOffset = Number(item.PageOffset ?? 0);

function asArray(x) {
  return Array.isArray(x) ? x : [];
}

function refId(refObj) {
  return refObj && typeof refObj.$ref === 'string'
    ? refObj.$ref
    : '';
}

function localPageNo(item) {
  const value = item?.prov?.[0]?.page_no;

  if (
    value === undefined ||
    value === null ||
    value === ''
  ) {
    return null;
  }

  const n = Number(value);

  return Number.isFinite(n)
    ? n
    : null;
}

/*
 * Vorerst Annahme: Docling page_no ist 1-basiert.
 * Falls wir später feststellen, dass page_no 0-basiert ist,
 * ändern wir genau diese Funktion.
 */
function globalPageNo(item) {
  const local = localPageNo(item);

  if (local === null) {
    return null;
  }

  return local + pageOffset;
}

function normalizeCellText(s) {
  return String(s || '')
    .trim()
    .replace(/\s+/g, ' ');
}

let document = {};

try {
  document =
    typeof item.DoclingJSON === 'string'
      ? JSON.parse(item.DoclingJSON)
      : item.DoclingJSON;
} catch (e) {
  throw new Error(
    `Part ${partNumber}: DoclingJSON ist kein gültiges JSON`
  );
}

const bodyChildren = asArray(document?.body?.children);
const texts = asArray(document?.texts);
const groups = asArray(document?.groups);
const tables = asArray(document?.tables);

const entries = [];

let lastLabel = '';
let textblock = '';
let heading = '';
let pageFrom = null;
let pageTo = null;

function findTextByRef(ref) {
  return texts.find(t => t?.self_ref === ref);
}

function pushTextEntry() {
  if (!textblock && !heading) {
    return;
  }

  entries.push({
    type: 'text',
    heading,
    text: textblock,
    page_from: pageFrom,
    page_to: pageTo,

    part_number: partNumber,
    part_id: partId
  });

  textblock = '';
  heading = '';
  pageFrom = null;
  pageTo = null;
}

function handleTextItem(t) {
  const label = t?.label || '';
  const original = t?.orig || '';
  const text = t?.text || '';
  const hyperlink = t?.hyperlink || '';

  const currentPage = globalPageNo(t);

  if (currentPage !== null) {
    pageTo = currentPage;

    if (pageFrom === null) {
      pageFrom = currentPage;
    }
  }

  if (label === 'section_header') {
    if (textblock) {
      pushTextEntry();
    }

    if (heading) {
      heading += '\n' + text;
    } else {
      heading = text;
    }
  }

  else if (label === 'list_item') {
    if (
      textblock &&
      !textblock.endsWith('\n')
    ) {
      textblock += '\n';
    }

    if (original) {
      textblock += original.trim();
    } else if (text) {
      textblock += `- ${text.trim()}`;
    }

    if (hyperlink) {
      textblock += ` (${hyperlink})`;
    }

    textblock += '\n';
  }

  else if (label === 'text') {
    if (
      textblock &&
      !/[ \n]$/.test(textblock)
    ) {
      textblock += ' ';
    }

    if (text) {
      textblock += text.trim();

      if (hyperlink) {
        textblock += ` (${hyperlink})`;
      }
    }
  }

  lastLabel = label;
}

function normalizeTable(tab) {
  const data = tab?.data || {};
  const cells = asArray(data.table_cells);

  let hasColumnHeaders = false;
  let maxRow = 0;
  let maxCol = 0;

  const defs = cells.map(tc => {
    const def = {
      text: normalizeCellText(tc?.text),
      row_header: !!tc?.row_header,
      column_header: !!tc?.column_header,
      row_span: tc?.row_span || 1,
      col_span: tc?.col_span || 1,
      start_row: tc?.start_row_offset_idx || 0,
      start_col: tc?.start_col_offset_idx || 0,
    };

    hasColumnHeaders ||= def.column_header;

    maxRow = Math.max(
      maxRow,
      def.start_row + def.row_span
    );

    maxCol = Math.max(
      maxCol,
      def.start_col + def.col_span
    );

    return def;
  });

  if (!maxRow || !maxCol) {
    return '';
  }

  const grid = Array.from(
    { length: maxRow },
    () =>
      Array.from(
        { length: maxCol },
        () => ({
          text: '',
          row_header: false,
          column_header: false,
        })
      )
  );

  for (const cell of defs) {
    for (
      let r = cell.start_row;
      r < cell.start_row + cell.row_span;
      r++
    ) {
      for (
        let c = cell.start_col;
        c < cell.start_col + cell.col_span;
        c++
      ) {
        grid[r][c].text =
          grid[r][c].text
            ? `${grid[r][c].text} / ${cell.text}`
            : cell.text;

        grid[r][c].row_header ||= cell.row_header;
        grid[r][c].column_header ||= cell.column_header;
      }
    }
  }

  const lines = [];

  if (!hasColumnHeaders) {
    for (let r = 0; r < maxRow; r++) {
      const line = grid[r]
        .map(c => c.text)
        .join(' ')
        .trim();

      if (line) {
        lines.push(line);
      }
    }
  } else {
    for (let r = 1; r < maxRow; r++) {
      const parts = [];

      for (let c = 0; c < maxCol; c++) {
        const header =
          grid[0][c].text ||
          `Column ${c + 1}`;

        const value =
          grid[r][c].text || '';

        parts.push(
          `${header}: ${value};`
        );
      }

      const line =
        parts.join(' ').trim();

      if (line) {
        lines.push(line);
      }
    }
  }

  return lines.join('\n').trim();
}

function handleTableRef(ref) {
  if (textblock || heading) {
    pushTextEntry();
  }

  const tab =
    tables.find(t => t?.self_ref === ref);

  if (!tab) {
    return;
  }

  const currentPage =
    globalPageNo(tab);

  let caption = '';

  for (const cap of asArray(tab.captions)) {
    const t =
      findTextByRef(refId(cap));

    if (t?.text) {
      caption += '\n' + t.text;
    }
  }

  const tableHeading =
    caption
      ? caption
          .replace(/\n/g, ' ')
          .trim()
      : '';

  const tableText =
    normalizeTable(tab);

  if (tableText) {
    entries.push({
      type: tableHeading
        ? 'table'
        : 'text',

      heading: tableHeading,
      text: tableText,

      page_from: currentPage,
      page_to: currentPage,

      part_number: partNumber,
      part_id: partId
    });
  }

  textblock = '';
  heading = '';
  pageFrom = null;
  pageTo = null;
  lastLabel = 'table';
}

for (const bc of bodyChildren) {
  const ref = refId(bc);

  if (!ref) {
    continue;
  }

  if (ref.includes('/texts/')) {
    const t =
      findTextByRef(ref);

    if (t) {
      handleTextItem(t);
    }
  }

  else if (ref.includes('/groups/')) {
    const group =
      groups.find(
        g => g?.self_ref === ref
      );

    for (
      const gc of asArray(group?.children)
    ) {
      const childRef =
        refId(gc);

      const t =
        findTextByRef(childRef);

      if (t) {
        handleTextItem(t);
      }
    }
  }

  else if (ref.includes('/tables/')) {
    handleTableRef(ref);
  }
}

if (textblock || heading) {
  pushTextEntry();
}

return {
  json: {
    PartID: partId,
    QueueID: Number(item.QueueID),
    TextUUID: item.TextUUID,

    PartNumber: partNumber,
    PageFrom: Number(item.PageFrom),
    PageTo: Number(item.PageTo),
    PageOffset: pageOffset,
    SourceType: item.SourceType,

    entries
